import csv
import io


def parse_csv(raw_csv: str):
    lines = raw_csv.splitlines(keepends=True)
    filtered = []
    in_quotes = False
    at_field_start = True

    for line in lines:
        body = line[:-2] if line.endswith("\r\n") else line[:-1] if line.endswith(("\r", "\n")) else line

        if not in_quotes and body.lstrip().startswith("#"):
            continue

        filtered.append(line)
        i = 0
        while i < len(body):
            char = body[i]
            if in_quotes:
                if char == '"':
                    if i + 1 < len(body) and body[i + 1] == '"':
                        i += 2
                        continue
                    in_quotes = False
                    at_field_start = False
            else:
                if char == ",":
                    at_field_start = True
                elif char == '"' and at_field_start:
                    in_quotes = True
                    at_field_start = False
                elif not (char.isspace() and at_field_start):
                    at_field_start = False
            i += 1

        if not in_quotes:
            at_field_start = True

    reader = csv.reader(io.StringIO("".join(filtered)), delimiter=",", quotechar='"', strict=False)
    records = [row for row in reader if row and any(value.strip() for value in row)]

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    width = len(columns)
    rows = []

    for record in records[1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width and width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
